import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { COLORS, EASINGS } from '../../brand';
import { FONT_BODY, FONT_MONO } from '../../fonts';
import { CLAMP } from '../../lib/kit';
import { CaptionTrack, CoverImage, HookTitle, ProgressBar, SAFE, ShortBg, ToolCard, Watermark, secToFrame } from '../../lib/shorts';
import { WORDS } from './words';

// short-113: generated by the daily batch. Cover held at frame 0; closes on the cover.
export const compositionConfig = { id: 'Short113', durationInSeconds: 33.7, fps: 30, width: 1080, height: 1920 };

const B0 = secToFrame(3.7);
const B1 = secToFrame(6.3);
const B2 = secToFrame(10.3);
const B3 = secToFrame(15.2);
const B4 = secToFrame(17.9);
const B5 = secToFrame(23.4);
const B6 = secToFrame(26.3);
const CTA = secToFrame(30.5);

const FadeOut: React.FC<{ at: number; children: React.ReactNode }> = ({ at, children }) => {
  const frame = useCurrentFrame();
  const op = 1 - interpolate(frame, [at - 8, at + 2], [0, 1], { ...CLAMP, easing: EASINGS.easeIn });
  return <AbsoluteFill style={{ opacity: op }}>{children}</AbsoluteFill>;
};

const Line: React.FC<{ k: string; v: string; good?: boolean; bad?: boolean }> = ({ k, v, good, bad }) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', fontFamily: FONT_MONO, fontSize: 32 }}>
    <span style={{ color: COLORS.d400 }}>{k}</span>
    <span style={{ color: bad ? COLORS.danger : good ? COLORS.signalAlt : COLORS.d300, fontWeight: good || bad ? 700 : 400 }}>{v}</span>
  </div>
);
const Panel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ background: COLORS.d900, borderRadius: 12, padding: '24px 26px', display: 'flex', flexDirection: 'column', gap: 16 }}>{children}</div>
);

const Short113: React.FC = () => {
  const frame = useCurrentFrame();
  const ctaOp = interpolate(frame, [CTA, CTA + 12], [0, 1], { ...CLAMP, easing: EASINGS.easeOut });
  return (
    <AbsoluteFill>
      <ShortBg />
      <FadeOut at={B0}>
        <CoverImage src="projects/short-113/cover.png" out={B0 - 10} />
        <HookTitle hold onDark kicker="AI SEARCH PRICING" lines={[{ text: "DEEPSEEK 75\u00a2" },{ text: "CLAUDE $10", accent: true }]} />
      </FadeOut>
      <FadeOut at={B1}>
        <ToolCard name="Claude + OpenAI" tagline="Per 1,000 searches." chip="$10 / 1K" at={B0 - 2} chipColor={COLORS.danger}>
          <Panel>
            <Line k="Claude web search" v="$10.00" bad />
            <Line k="OpenAI web search" v="$10.00" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B2}>
        <ToolCard name="Google" tagline="Gemini 3 and newer." chip="5,000 FREE" at={B1 - 2}>
          <Panel>
            <Line k="free / month" v="5,000" good />
            <Line k="then / 1K" v="$14.00" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B3}>
        <ToolCard name="DeepSeek Search" tagline="Successful requests." chip="$0.75 / 1K" at={B2 - 2}>
          <Panel>
            <Line k="per 1,000" v="$0.75" good />
            <Line k="Claude" v="$10.00" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B4}>
        <ToolCard name="From Nov 1" tagline="Billing starts." chip="NOV 1" at={B3 - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="billed from" v="Nov 1 2026" />
            <Line k="rate / 1K" v="$0.75" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B5}>
        <ToolCard name="Until then" tagline="Harness, Claude Code, Codex." chip="FREE" at={B4 - 2}>
          <Panel>
            <Line k="server-side calls" v="$0.00" good />
            <Line k="billing" v="not yet" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B6}>
        <ToolCard name="13x cheaper" tagline="Than Claude." chip="13X" at={B5 - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="DeepSeek" v="$0.75" good />
            <Line k="Claude" v="$10.00" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={CTA}>
        <ToolCard name="Tokens extra" tagline="For everyone." chip="COUNT THEM" at={B6 - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="search fee" v="per 1,000" />
            <Line k="+ tokens" v="always" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <AbsoluteFill style={{ opacity: ctaOp }}>
        <CoverImage src="projects/short-113/cover.png" at={CTA} />
        <HookTitle hold onDark at={CTA} kicker="AI SEARCH PRICING" lines={[{ text: "DEEPSEEK 75\u00a2" },{ text: "CLAUDE $10", accent: true }]} />
        <div style={{ position: 'absolute', left: SAFE.side, right: SAFE.side, top: SAFE.top + 520, textAlign: 'center', fontFamily: FONT_BODY, fontWeight: 600, fontSize: 44, color: 'rgba(255,255,255,0.82)' }}>
          Ten dollars versus 75 cents.
        </div>
      </AbsoluteFill>
      <CaptionTrack words={WORDS} />
      <Watermark at={12} />
      <ProgressBar />
    </AbsoluteFill>
  );
};
export default Short113;
